// Recuperamos la lista completa de productos
const items = $input.all();

// Obtenemos el nombre de la categoría
const categoriaElegida = items[0]?.json.categoria || 'Seleccionada';

// Filtramos solo productos con stock
const productosDisponibles = items.filter(item => Number(item.json.stock || 0) > 0);

// Si no hay productos disponibles
if (productosDisponibles.length === 0) {
  return [{
    json: {
      categoria: categoriaElegida,
      mensaje_menu:
`❌ Elegiste: ${categoriaElegida}

Lo sentimos, en este momento todos los productos de esta categoría están agotados.`
    }
  }];
}

let listaMenu = "";

// Construimos la lista
productosDisponibles.forEach((item, index) => {
  const p = item.json;

  listaMenu += `${index + 1}. ${p.nombre}
   📝 ${p.descripcion}
   💲 Precio: $${Number(p.precio).toLocaleString('es-CO')}
   📦 Stock disponible: ${p.stock}

`;
});

// Devolvemos el mensaje
return [{
  json: {
    categoria: categoriaElegida,
    mensaje_menu:
`✅ Elegiste: ${categoriaElegida}

Estas son las opciones disponibles:

${listaMenu}👉 Escribe el nombre del producto que deseas pedir.`
  }
}];

// 1. Datos de la SESIÓN en Google Sheets
const sesion = $('Get row(s) in sheet3').item.json;
const productoBuscado = String(sesion.carrito_temporal || '').trim().toLowerCase();

// 2. Leemos la CANTIDAD REAL recibida en el paso previo
const cantidadEntrada = $('Append or update row in sheet5').item.json.cantidad 
  || $input.first().json.cantidad 
  || sesion.cantidad 
  || 1;

const cantidadDeseada = parseInt(cantidadEntrada, 10);

// 3. Traemos TODOS los productos del MENÚ (Get row(s) in sheet4)
const menuCompleto = $('Get row(s) in sheet4').all();

// 4. Buscamos en el menú el producto que coincida
const productoEncontrado = menuCompleto.find(item => {
  const nombreMenu = String(item.json.nombre || '').trim().toLowerCase();
  return nombreMenu === productoBuscado;
});

// 5. Validamos si existe el producto
if (!productoEncontrado) {
  return [{
    json: {
      resultado: 0,
      carrito_temporal: sesion.carrito_temporal,
      mensaje: `❌ No se encontró el producto "${sesion.carrito_temporal}" en el menú.`
    }
  }];
}

const prod = productoEncontrado.json;
const stockDisponible = parseInt(prod.stock || 0, 10);
const precioUnitario = Number(prod.precio || 0);

// 6. VALIDACIÓN CRÍTICA DE STOCK
if (cantidadDeseada > stockDisponible) {
  // NO alcanza el stock -> mandamos resultado 0
  return [{
    json: {
      resultado: 0,
      id_producto: prod.id_producto,
      nombre: prod.nombre,
      cantidad_solicitada: cantidadDeseada,
      stock_disponible: stockDisponible,
      mensaje: `❌ Lo sentimos, no hay suficiente stock. Solicitaste ${cantidadDeseada} unidad(es), pero solo quedan ${stockDisponible} disponible(s).`
    }
  }];
}

// 7. SI ALCANZA EL STOCK -> Calculamos y mandamos resultado 1
const totalPagar = precioUnitario * cantidadDeseada;
const nuevoStock = stockDisponible - cantidadDeseada;

return [{
  json: {
    resultado: 1,
    id_producto: prod.id_producto,
    nombre: prod.nombre,
    precio_unitario: precioUnitario,
    cantidad_solicitada: cantidadDeseada,
    total_pagar: totalPagar,
    stock_anterior: stockDisponible,
    nuevo_stock: nuevoStock,
    row_number: prod.row_number,
    mensaje: `✅ Reservado: ${cantidadDeseada}x ${prod.nombre}. Total: $${totalPagar}`
  }
}];

