// 1. Obtenemos el texto del mensaje enviado por el usuario
// (Asegúrate de ajustar si tu texto viene de un nodo anterior como 'Telegram Trigger' o 'Normalizar')
const datosMensaje = $('Telegram Trigger').item.json;
const textoIngresado = (datosMensaje.message?.text || datosMensaje.text || '').trim().toLowerCase();

// 2. Evaluamos si es 'y' o 'n'
if (textoIngresado === 'y' || textoIngresado === 'n') {
  return [{
    json: {
      resultado: 1,
      opcion: textoIngresado === 'y' ? 'SI' : 'NO', // 'SI' si fue 'y', 'NO' si fue 'n'
      mensaje: `Respuesta válida: ${textoIngresado.toUpperCase()}`
    }
  }];
} else {
  return [{
    json: {
      resultado: 0,
      opcion: null,
      mensaje: "Respuesta no válida. Por favor, responde con 'Y' para Sí o 'N' para No."
    }
  }];
}

// Tomamos únicamente el ÚLTIMO registro del usuario (el más reciente)
const ultimoRegistro = $input.all().pop();

return [ultimoRegistro];

// 1. Obtenemos el valor de la opción del nodo anterior (If2 o Telegram Trigger)
const itemEntrada = $input.first().json;

// Leemos el texto ya sea del campo 'opcion', 'mensaje' o del texto directo de Telegram
const textoRecibido = String(
  itemEntrada.opcion || 
  itemEntrada.mensaje || 
  $('Telegram Trigger').item.json.message?.text || 
  ''
).trim().toLowerCase();

// 2. Evaluamos la respuesta con la lógica requerida:
if (textoRecibido === 'no' || textoRecibido === 'n' || textoRecibido.includes('no')) {
  // Si respondió NO -> Devuelve 1
  return [{
    json: {
      resultado: 1,
      opcion: 'NO',
      mensaje: 'El usuario eligió NO.'
    }
  }];
} else if (textoRecibido === 'si' || textoRecibido === 'sí' || textoRecibido === 's' || textoRecibido === 'y') {
  // Si respondió SÍ -> Devuelve 0
  return [{
    json: {
      resultado: 0,
      opcion: 'SI',
      mensaje: 'El usuario eligió SÍ.'
    }
  }];
} else {
  // Opción no reconocida
  return [{
    json: {
      resultado: -1,
      opcion: null,
      mensaje: 'Respuesta inválida. Debe ser SÍ o NO.'
    }
  }];
}

// 1. Leemos todos los ítems recibidos del nodo que consulta los pedidos
const itemsPedidos = $('Get row(s) in sheet7').all();

let listaProductos = [];
let totalAcumulado = 0;

// 2. Recorremos todas las filas registradas para este usuario
for (const item of itemsPedidos) {
  const datos = item.json;

  // Obtenemos nombre y cantidad
  const nombreProd = datos.detalles_pedido || datos.nombre || datos.carrito_temporal || 'Producto';
  const cantidad = parseInt(datos.cantidad || 1, 10);

  // Tomamos directamente el total guardado en la hoja (ya calculado previamente)
  const totalFila = Number(datos.total_pago || datos.total_pagar || datos.precio || 0);

  // Guardamos el detalle en la lista y sumamos al total acumulado
  listaProductos.push(`• ${nombreProd} (x${cantidad})`);
  totalAcumulado += totalFila;
}

// 3. Formateamos la lista de productos y el texto final
const textoProductos = listaProductos.join('\n');
const totalFormateado = totalAcumulado.toLocaleString('es-CO');

const mensajeResumen = `🛒 *RESUMEN DE TU PEDIDO*\n\n` +
  `*Productos elegidos:*\n${textoProductos}\n\n` +
  `💰 *Total a pagar:* $${totalFormateado}\n\n` +
  `💳 *Selecciona tu método de pago:*\n` +
  `1️⃣ Opción 1: Transferencia\n` +
  `2️⃣ Opción 2: Efectivo\n\n` +
  `_Por favor, responde con el número de tu opción (1 o 2)._`;

// 4. Retornamos los datos para enviarlos por Telegram
return [{
  json: {
    mensaje_resumen: mensajeResumen,
    total_acumulado: totalAcumulado,
    cantidad_items: itemsPedidos.length
  }
}];

// 1. Leemos el texto ingresado por el usuario desde Telegram Trigger
const datosTelegram = $('Telegram Trigger').item.json;
const textoIngresado = String(
  datosTelegram.message?.text || 
  datosTelegram.text || 
  ''
).trim();

// 2. Validamos si la respuesta es exactamente "1" o "2"
if (textoIngresado === '1' || textoIngresado === '2') {
  // Elige 1 o 2 -> Devuelve 0
  const metodo = textoIngresado === '1' ? 'Transferencia' : 'Efectivo';

  return [{
    json: {
      resultado: 0,
      opcion_elegida: textoIngresado,
      metodo_pago: metodo,
      mensaje: `Método de pago seleccionado: ${metodo}`
    }
  }];
} else {
  // No elige ninguna de las dos -> Devuelve 1
  return [{
    json: {
      resultado: 1,
      opcion_elegida: textoIngresado,
      metodo_pago: null,
      mensaje: "Opción no válida. Por favor, responde con 1 para Transferencia o 2 para Efectivo."
    }
  }];
}

// 1. Obtenemos los datos del nodo anterior
const itemEntrada = $input.first().json;

// Leemos 'opcion_elegida' o en su defecto el texto del Telegram Trigger
const opcion = String(
  itemEntrada.opcion_elegida || 
  $('Telegram Trigger').item.json.message?.text || 
  ''
).trim();

// 2. Evaluamos la opción elegida
if (opcion === '1') {
  // Opción 1 (Transferencia) -> Devuelve 0
  return [{
    json: {
      resultado: 0,
      opcion_elegida: '1',
      metodo_pago: 'Transferencia',
      mensaje: 'Seleccionó Transferencia (Opción 1)'
    }
  }];
} else if (opcion === '2') {
  // Opción 2 (Efectivo) -> Devuelve 1
  return [{
    json: {
      resultado: 1,
      opcion_elegida: '2',
      metodo_pago: 'Efectivo',
      mensaje: 'Seleccionó Efectivo (Opción 2)'
    }
  }];
} else {
  // Por si llega un valor distinto a 1 o 2
  return [{
    json: {
      resultado: -1,
      opcion_elegida: opcion,
      metodo_pago: null,
      mensaje: 'Opción no válida'
    }
  }];
};

// 1. Obtenemos los datos traídos de Google Sheets (Get row(s) in sheet8)
const datosUsuario = $('Get row(s) in sheet8').item.json;

// 2. Leemos los puntos actuales (si está vacío o no existe, arranca en 0)
const puntosActuales = parseInt(datosUsuario.puntos_lealtad || 0, 10);

// 3. Le sumamos 1 punto
const nuevosPuntos = puntosActuales + 1;

// 4. Retornamos los datos actualizados
return [{
  json: {
    ...datosUsuario, // Mantiene todos los datos del usuario (telegram_id, nombre, etc.)
    puntos_lealtad: nuevosPuntos,
    puntos_anteriores: puntosActuales,
    mensaje: `¡Puntos actualizados! Tenías ${puntosActuales} y ahora tienes ${nuevosPuntos}.`
  }
}];

// 1. Leemos todas las filas del pedido que vienen de Get row(s) in sheet7
const filasPedidos = $('Get row(s) in sheet7').all();

if (filasPedidos.length === 0) {
  return [];
}

// 2. Calculamos el total acumulado sumando todas las filas
let totalConsolidado = 0;
for (const item of filasPedidos) {
  totalConsolidado += Number(item.json.total_pago || item.json.total_pagar || 0);
}

// 3. Tomamos ÚNICAMENTE la última fila (el último registro creado)
const ultimaFila = filasPedidos[filasPedidos.length - 1].json;

// 4. Retornamos solo esa última fila con el Total de la Orden consolidado
return [{
  json: {
    row_number: ultimaFila.row_number,
    id_pedido: ultimaFila.id_pedido,
    id_usuario: ultimaFila.id_usuario,
    detalles_pedido: ultimaFila.detalles_pedido,
    cantidad: ultimaFila.cantidad,
    total_pago: ultimaFila.total_pago,
    Pago_en_total: totalConsolidado, // Total acumulado de todos los productos
    estado: ultimaFila.estado,
    fecha: ultimaFila.fecha,
    hora: ultimaFila.hora
  }
}];

// 1. Leemos las 2 filas que salieron de Get row(s) in sheet10
const filasPedidos = $('Get row(s) in sheet10').all();

// 2. Mapeamos cada una enviando su row_number y el estado "Entregado"
return filasPedidos.map(item => {
  return {
    json: {
      row_number: item.json.row_number,
      estado: "Entregado"
    }
  };
});

// 1. Apuntamos al nombre exacto del nodo previo: Get row(s) in sheet11
const pedidos = $('Get row(s) in sheet11').all();

// Fecha de hoy (YYYY-MM-DD)
const hoy = new Date().toISOString().split('T')[0];

// Si no hubo ventas hoy
if (pedidos.length === 0) {
  return [{
    json: {
      fecha: hoy,
      total_vendido: 0,
      cantidad_pedidos: 0,
      producto_estrella: "Sin ventas",
      hora_pico: "N/A"
    }
  }];
}

let totalVendido = 0;
const conteoProductos = {};
const conteoHoras = {};

// 2. Procesamos cada fila de la pestaña PEDIDOS
for (const item of pedidos) {
  const p = item.json;

  // Sumamos las ventas (monto por ítem)
  const monto = Number(p.total_pago || 0);
  totalVendido += monto;

  // Contador para Producto Estrella
  const producto = p.detalles_pedido || "Desconocido";
  const cantidad = parseInt(p.cantidad || 1, 10);
  conteoProductos[producto] = (conteoProductos[producto] || 0) + cantidad;

  // Contador para Hora Pico (tomando la hora base HH:00)
  if (p.hora) {
    const horaBase = String(p.hora).split(':')[0] + ":00";
    conteoHoras[horaBase] = (conteoHoras[horaBase] || 0) + 1;
  }
}

// 3. Determinamos el Producto Estrella (el más vendido por cantidad)
let productoEstrella = "N/A";
let maxCantProd = 0;
for (const [prod, cant] of Object.entries(conteoProductos)) {
  if (cant > maxCantProd) {
    maxCantProd = cant;
    productoEstrella = `${prod} (${cant} un.)`;
  }
}

// 4. Determinamos la Hora Pico (hora con mayor cantidad de registros)
let horaPico = "N/A";
let maxPedidosHora = 0;
for (const [hora, cant] of Object.entries(conteoHoras)) {
  if (cant > maxPedidosHora) {
    maxPedidosHora = cant;
    horaPico = `${hora} (${cant} pedidos)`;
  }
}

// 5. Retornamos los datos para insertar en la hoja REPORTES
return [{
  json: {
    fecha: hoy,
    total_vendido: totalVendido,
    cantidad_pedidos: pedidos.length,
    producto_estrella: productoEstrella,
    hora_pico: horaPico
  }
}];

