// 1. Obtenemos todos los ítems que vienen de la actualización previa
const items = $input.all();

// Si no hay ítems, retornamos un arreglo vacío
if (items.length === 0) {
  return [];
}

// 2. Tomamos la información general desde el primer ítem
const primerItem = items[0].json;

// 3. (Opcional) Si quieres armar la lista combinada de productos para el mensaje final:
const listaProductos = items
  .map(item => `- ${item.json.detalles_pedido} (x${item.json.cantidad || 1})`)
  .join('\n');

// 4. Retornamos UN SOLO ÍTEM hacia el siguiente nodo (el de Telegram)
return [{
  json: {
    telegram_id: primerItem.id_usuario || primerItem.telegram_id,
    resumen_pedido: listaProductos,
    mensaje_final: "🎉 *¡Tu pedido ha sido procesado con éxito!*\n\nEn breve la cocina comenzará a prepararlo. ¡Muchas gracias por tu compra!"
  }
}];

// Recuperamos la lista completa de productos
const items = $input.all();

// Obtenemos el nombre de la categoría
const categoriaElegida = items[0]?.json.categoria || 'Seleccionada';

// Filtramos solo productos con stock
const productosDisponibles = items.filter(item => Number(item.json.stock || 0) > 0);

// Si no hay productos disponibles
if (productosDisponibles.length === 0) {
  return [{
    json: {
      categoria: categoriaElegida,
      mensaje_menu:
`❌ Elegiste: ${categoriaElegida}

Lo sentimos, en este momento todos los productos de esta categoría están agotados.`
    }
  }];
}

let listaMenu = "";

// Construimos la lista
productosDisponibles.forEach((item, index) => {
  const p = item.json;

  listaMenu += `${index + 1}. ${p.nombre}
   📝 ${p.descripcion}
   💲 Precio: $${Number(p.precio).toLocaleString('es-CO')}
   📦 Stock disponible: ${p.stock}

`;
});

// Devolvemos el mensaje
return [{
  json: {
    categoria: categoriaElegida,
    mensaje_menu:
`✅ Elegiste: ${categoriaElegida}

Estas son las opciones disponibles:

${listaMenu}👉 Escribe el número o el nombre del producto que deseas pedir.`
  }
}];

// 1. Leemos TODAS las filas que trajo el nodo de Google Sheets para esa categoría
// (Si en tu canvas ese nodo se llama distinto a 'Get row(s) in sheet', ajusta el nombre dentro del $('...'))
const productosCategoria = $('Get row(s) in sheet').all();

// 2. Sumamos el stock de todos los productos encontrados en la categoría
let stockTotalCategoria = 0;

for (const item of productosCategoria) {
  const stockProducto = Number(item.json.stock || 0);
  stockTotalCategoria += stockProducto;
}

// 3. Evaluamos si hay al menos 1 producto con stock disponible
const hayDisponible = stockTotalCategoria > 0 ? 1 : 0;

// 4. Tomamos la información previa (categoría y mensaje_menu)
const datosPrevios = $input.first().json;

// Si no hay stock, cambiamos el mensaje para avisar que está agotada la categoría
let mensajeFinal = datosPrevios.mensaje_menu;
if (hayDisponible === 0) {
  mensajeFinal = `❌ Lo sentimos, actualmente todos los productos de la categoría *${datosPrevios.categoria || 'seleccionada'}* están agotados.`;
}

// 5. Devolvemos UN SOLO objeto con la variable disponible (1 o 0)
return [{
  json: {
    ...datosPrevios,
    mensaje_menu: mensajeFinal,
    disponible: hayDisponible,
    stock_total_categoria: stockTotalCategoria
  }
}];

// 1. Tomamos los datos recibidos del nodo anterior
const item = $input.first().json;

// 2. Extraemos el valor del campo 'cantidad' y lo limpiamos de espacios
const entrada = String(item.cantidad || '').trim();

// 3. Expresión regular que valida que SOLO sean dígitos numéricos enteros (ej: 1, 2, 5)
const esNumeroValido = /^\d+$/.test(entrada);

// 4. Asignamos 1 si es número válido o 0 si contiene letras/símbolos
const esNumeroFlag = esNumeroValido ? 1 : 0;

// 5. Devolvemos el objeto con el indicador para el nodo IF posterior
return [{
  json: {
    ...item,
    cantidad_ingresada: entrada,
    es_numero: esNumeroFlag,
    mensaje_error: esNumeroFlag === 0 ? "⚠️ Por favor, ingresa solo un número válido para la cantidad (ejemplo: 1, 2, 3)." : null
  }
}];;

// 1. Buscamos el texto directamente desde el evento de Telegram Trigger
// (Ajusta 'Telegram Trigger' si en tu lienzo el nodo tiene otro nombre exacto)
const telegramData = $('Telegram Trigger').first()?.json;

// 2. Extraemos el texto enviado por el usuario o de un callback/botón si fuera el caso
const textoRaw = telegramData?.message?.text 
  || telegramData?.callback_query?.data 
  || $input.first().json?.cantidad 
  || '';

// 3. Limpiamos el texto y lo convertimos a string/minúsculas
const textoEntrada = String(textoRaw).trim().toLowerCase();

// 4. Lista de opciones permitidas
const opcionesValidas = ['1', '2', 'pedir', 'historial de pedidos'];

// 5. Validamos si está en la lista
const esOpcionValida = opcionesValidas.includes(textoEntrada) ? 1 : 0;

// 6. Retornamos el resultado
return [{
  json: {
    ...$input.first().json,
    opcion_ingresada: textoRaw,
    es_valido: esOpcionValida,
    mensaje_error: esOpcionValida === 0 ? "⚠️ Opción no válida. Por favor, selecciona '1' (Pedir), '2' (Historial de pedidos) o usa los botones del menú." : null
  }
}];

// 1. Obtenemos el ítem recibido de la entrada
const item = $input.first().json;

// 2. Extraemos 'opcion_ingresada' y la convertimos a minúsculas y sin espacios
const opcion = String(item.opcion_ingresada || '').trim().toLowerCase();

// 3. Evaluamos la ruta según lo ingresado:
// Si es '2' o 'historial de pedidos' -> 1
// Si es '1' o 'pedir' -> 0
let ruta = 0;

if (opcion === '2' || opcion === 'historial de pedidos') {
  ruta = 1;
} else if (opcion === '1' || opcion === 'pedir') {
  ruta = 0;
}

// 4. Retornamos el objeto con el campo 'ruta' (0 o 1)
return [{
  json: {
    ...item,
    ruta: ruta
  }
}];

// 1. Obtenemos todos los pedidos traídos desde el nodo de Sheets
// (Si en tu lienzo el nodo se llama distinto a 'Get row(s) in sheet12', ajusta la etiqueta)
const pedidos = $('Get row(s) in sheet12').all();

// 2. Si no hay pedidos registrados para ese usuario, enviamos 0 directamente
if (pedidos.length === 0) {
  return [{
    json: {
      tiene_pedidos_entregados: 0,
      mensaje: "Aún no tienes historial de pedidos entregados."
    }
  }];
}

// 3. Verificamos si existe al menos UN pedido con estado "Entregado"
const existeEntregado = pedidos.some(item => {
  const estado = String(item.json.estado || '').trim().toLowerCase();
  return estado === 'entregado';
});

// 4. Asignamos la bandera (1 si tiene entregados, 0 si no)
const flagEntregados = existeEntregado ? 1 : 0;

// 5. Retornamos UN SOLO objeto consolidado para controlar el nodo IF
return [{
  json: {
    ...$input.first().json,
    tiene_pedidos_entregados: flagEntregados,
    total_pedidos_encontrados: pedidos.length,
    mensaje: flagEntregados === 1 
      ? "✅ Usuario con historial de pedidos entregados." 
      : "⚠️ El usuario no tiene pedidos finalizados con estado 'Entregado'."
  }
}];

// 1. Leemos todos los registros del nodo de Google Sheets
const todasLasFilas = $('Get row(s) in sheet12').all();

// 2. Filtramos ÚNICAMENTE las filas con estado 'Entregado'
const filasEntregadas = todasLasFilas.filter(item => {
  const estado = String(item.json.estado || '').trim().toLowerCase();
  return estado === 'entregado';
});

// 3. Si no hay pedidos entregados, retornamos un mensaje preventivo
if (filasEntregadas.length === 0) {
  return [{
    json: {
      mensaje_historial: "📜 HISTORIAL DE PEDIDOS ENTREGADOS\n\n⚠️ No tienes pedidos entregados registrados."
    }
  }];
}

// 4. Agrupamos por id_pedido (o combinación fecha + hora como identificador único)
const pedidosAgrupados = {};

filasEntregadas.forEach((item) => {
  const data = item.json;
  const idPedido = data.id_pedido || `${data.fecha || ''} ${data.hora || ''}`.trim() || 'Pedido';

  if (!pedidosAgrupados[idPedido]) {
    const fechaHora = data.fecha && data.hora ? `${data.fecha} ${data.hora}` : (data.fecha || data.hora || '');

    pedidosAgrupados[idPedido] = {
      fechaHora: fechaHora,
      productos: []
    };
  }

  const cantidad = Number(data.cantidad || 1);
  const totalItem = Number(data.total_pago || 0);
  const valorUnitario = cantidad > 0 ? (totalItem / cantidad) : totalItem;

  pedidosAgrupados[idPedido].productos.push({
    nombre: data.detalles_pedido || 'Producto',
    cantidad: cantidad,
    valorUnitario: valorUnitario,
    pagado: totalItem
  });
});

// 5. Construimos el mensaje con emojis y sin comas al final
let textoHistorial = "📜 HISTORIAL DE PEDIDOS ENTREGADOS\n\n";
let contadorPedido = 1;

for (const id in pedidosAgrupados) {
  const pedido = pedidosAgrupados[id];

  textoHistorial += `📦 ${contadorPedido} Pedido realizado (${pedido.fechaHora})\n`;

  pedido.productos.forEach((prod) => {
    textoHistorial += `🍔 Producto: ${prod.nombre}\n`;
    textoHistorial += `🔢 Cantidad: ${prod.cantidad}\n`;
    textoHistorial += `🏷️ Valor unitario: $${prod.valorUnitario.toLocaleString()}\n`;
    textoHistorial += `💰 Pagado: $${prod.pagado.toLocaleString()}\n`;
  });

  textoHistorial += `-----------------------------------\n`;

  contadorPedido++;
}

// 6. Retornamos el objeto consolidado
return [{
  json: {
    ...$input.first().json,
    mensaje_historial: textoHistorial.trim()
  }
}];
